        assignee,
        floater_or_not
    from {{ ref('stg_card_dtls') }}
    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_DOCUMENT_BK__CARD_NO, HUB_POLICY_BK__POLICY_REF order by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_DOCUMENT_BK__CARD_NO, HUB_POLICY_BK__POLICY_REF) = 1
),

t1 as (
