    from {{ ref('stg_ecard_pol_dtls_config') }}
    qualify row_number() over (partition by HUB_POLICY_BK__POLICY_REF, HUB_QUOTE_BK__QUOTE_REF order by HUB_POLICY_BK__POLICY_REF, HUB_QUOTE_BK__QUOTE_REF) = 1
),

t2 as (
    select
        nullif(trim(SCRUTINY_NO),'') as HUB_ASSESSMENT_BK__SCRUTINY_NO,
