    from {{ ref('stg_enroll_scr_dtls') }}
    qualify row_number() over (partition by HUB_ASSESSMENT_BK__SCRUTINY_NO, HUB_POLICY_BK__CONTRACT_ID, HUB_QUOTE_BK__QUOTATION_NO order by HUB_ASSESSMENT_BK__SCRUTINY_NO, HUB_POLICY_BK__CONTRACT_ID, HUB_QUOTE_BK__QUOTATION_NO) = 1
),

t3 as (
