    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__PARTNERID, HUB_POLICY_BK__PMASTERPOLICYNUMBER, intermediary order by HUB_DISTRIBUTION_CHANNEL_BK__PARTNERID, HUB_POLICY_BK__PMASTERPOLICYNUMBER, intermediary) = 1
),

t4 as (
