),

t6 as (
    select
        nullif(trim(USER_TRANS_KEY_NO),'') as HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO,
        md5(normalise(upper(nullif(trim( coalesce(ADDRESS_1,'') || ' ' || coalesce(ADDRESS_2,'') || ' ' || coalesce(PINCODE,'') ),'')))) as HUB_LOCATION_BK__ADDRESS_1_ADDRESS_2_PINCODE,
        md5(normalise(upper(nullif(coalesce(nullif(trim(POLICY_REF),''),'') || '|NOMINEE|' || coalesce(nullif(trim(NOMINEENAME),''),''), '|NOMINEE|')))) as HUB_PARTY_BK__POLICY_REF_NOMINEE_NOMINEENAME,
        nullif(trim(CUST_ID),'') as HUB_PARTY_BK__CUST_ID,
        nullif(trim(POLICY_REF),'') as HUB_POLICY_BK__POLICY_REF,
        nullif('CUSTID:' || nullif(trim(CUST_ID),''), 'CUSTID:') as HUB_RISK_OBJECT_BK__CUSTID_CUST_ID,
        imd_code
    from {{ ref('stg_pmsby_data_web_service') }}
    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO, HUB_LOCATION_BK__ADDRESS_1_ADDRESS_2_PINCODE, HUB_POLICY_BK__POLICY_REF, HUB_RISK_OBJECT_BK__CUSTID_CUST_ID order by HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO, HUB_LOCATION_BK__ADDRESS_1_ADDRESS_2_PINCODE, HUB_POLICY_BK__POLICY_REF, HUB_RISK_OBJECT_BK__CUSTID_CUST_ID) = 1
),

t7 as (
    select
        nullif('TXN:' || nullif(trim(TRANSACTION_ID),''), 'TXN:') as HUB_FINANCIAL_TRANSACTION_BK__TXN_TRANSACTION_ID,
        md5(normalise(upper(nullif(trim(MAILING_PINCODE),'')))) as HUB_LOCATION_BK__MAILING_PINCODE,
        md5(normalise(upper(nullif(trim(PREV_INSURER_ADD),'')))) as HUB_LOCATION_BK__PREV_INSURER_ADD,
        nullif(trim(DEPARTMENT_CODE),'') as HUB_ORG_UNIT_BK__DEPARTMENT_CODE,
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        nullif('PRODUCT:' || nullif(trim(PRODUCT_4DIGIT_CODE),''), 'PRODUCT:') as HUB_PRODUCT_BK__PRODUCT_PRODUCT_4DIGIT_CODE,
        brokerage_amt,
        dealer_code,
        main_agent_code,
        main_agent_comm_amt,
        main_agent_comm_rate,
        main_agent_sc_amt,
        main_agent_sc_rate,
        refered_by_rule_engine,
        referral_reason,
        refer_by,
        refer_date,
        sub_agent_code,
        sub_agent_comm_amt,
        sub_agent_comm_rate
    from {{ ref('stg_policy_bases_extn') }}
    qualify row_number() over (partition by HUB_FINANCIAL_TRANSACTION_BK__TXN_TRANSACTION_ID, HUB_ORG_UNIT_BK__DEPARTMENT_CODE, HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__PRODUCT_PRODUCT_4DIGIT_CODE order by HUB_FINANCIAL_TRANSACTION_BK__TXN_TRANSACTION_ID, HUB_ORG_UNIT_BK__DEPARTMENT_CODE, HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__PRODUCT_PRODUCT_4DIGIT_CODE) = 1
),

t8 as (
    select
        md5(normalise(upper(nullif(coalesce(nullif(trim(ADDRESS),''),'') || '|' || coalesce(nullif(trim(CITY),''),'') || '|' || coalesce(nullif(trim(REGION),''),''), '||')))) as HUB_LOCATION_BK__ADDRESS_CITY_REGION,
        md5(normalise(upper(nullif(coalesce(nullif(trim(INSURED_ADDRESS),''),'') || '|' || coalesce(nullif(trim(PINCODE),''),''), '|')))) as HUB_LOCATION_BK__INSURED_ADDRESS_PINCODE,
        md5(normalise(upper(nullif(trim(MAILING_PINCODE),'')))) as HUB_LOCATION_BK__MAILING_PINCODE,
        nullif(trim(BRANCH_CODE),'') as HUB_ORG_UNIT_BK__BRANCH_CODE,
        nullif(trim(DEPARTMENT_CODE),'') as HUB_ORG_UNIT_BK__DEPARTMENT_CODE,
        md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|')))) as HUB_PARTY_BK__CONTRACT_ID_INSURED_INSURED_NAME,
        nullif('PARTID:' || nullif(trim(PART_ID),''), 'PARTID:') as HUB_PARTY_BK__PARTID_PART_ID,
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        nullif('PRODUCT:' || nullif(trim(PRODUCT_CODE),''), 'PRODUCT:') as HUB_PRODUCT_BK__PRODUCT_PRODUCT_CODE,
