    coalesce(t0.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, t3.HUB_DISTRIBUTION_CHANNEL_BK__PARTNERID, t5.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, t6.HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO) as HUB_DISTRIBUTION_CHANNEL_BK,
