    coalesce(t5.HUB_PRODUCT_BK__PRODUCT_CODE, t7.HUB_PRODUCT_BK__PRODUCT_PRODUCT_4DIGIT_CODE, t8.HUB_PRODUCT_BK__PRODUCT_PRODUCT_CODE, t9.HUB_PRODUCT_BK__PRODUCT) as HUB_PRODUCT_BK,
