    t3.HUB_LOCATION_BK__LOCATIONCODE as T3__HUB_LOCATION_BK__LOCATIONCODE,
    t3.HUB_LOCATION_BK__ORPHAN_LOC as T3__HUB_LOCATION_BK__ORPHAN_LOC,
    t3.HUB_LOCATION_BK__POLICY_LOCATION as T3__HUB_LOCATION_BK__POLICY_LOCATION,
    t3.HUB_LOCATION_BK__RISK_LOCATION as T3__HUB_LOCATION_BK__RISK_LOCATION,
    t3.HUB_PRODUCT_BK__PLANID as T3__HUB_PRODUCT_BK__PLANID,
    t3.HUB_PRODUCT_BK__SCHEMECODE as T3__HUB_PRODUCT_BK__SCHEMECODE,
    t6.HUB_PARTY_BK__POLICY_REF_NOMINEE_NOMINEENAME as T6__HUB_PARTY_BK__POLICY_REF_NOMINEE_NOMINEENAME,
    t6.HUB_PARTY_BK__CUST_ID as T6__HUB_PARTY_BK__CUST_ID,
