    t9.HUB_ORG_UNIT_BK__DEPARTMENT as T9__HUB_ORG_UNIT_BK__DEPARTMENT,
    t9.HUB_POLICY_BK__POLICY_NO as T9__HUB_POLICY_BK__POLICY_NO,
    t9.HUB_POLICY_BK__PREV_POL_REF as T9__HUB_POLICY_BK__PREV_POL_REF,
    t9.HUB_POLICY_BK__REG_NO as T9__HUB_POLICY_BK__REG_NO,
    t0.assignee as ASSIGNEE_REFERENCE,
    t7.brokerage_amt as BROKERAGE_AMOUNT,
    t4.service_charge_amt as CHARGE_AMOUNT,
    t4.service_charge_rate as CHARGE_RATE,
    coalesce(t7.main_agent_comm_amt, t7.sub_agent_comm_amt, t8.main_agent_comm_amt, t8.sub_agent_comm_amt) as COMMISSION_AMOUNT,
    coalesce(t2.commision, t7.main_agent_comm_rate, t7.sub_agent_comm_rate, t8.main_agent_comm_rate, t8.sub_agent_comm_rate) as COMMISSION_RATE,
    t1.comp_contr as CONTRIBUTORY_INDICATOR,
    coalesce(t7.dealer_code, t8.dealer_code) as DEALER_CODE,
    t2.no_of_dependents as DEPENDENT_MEMBER_COUNT,
    t2.relationship as ELIGIBLE_RELATIONSHIP_SET,
    t1.comp_contr_amt as EMPLOYER_CONTRIBUTION_AMOUNT,
    t1.comp_cntrper as EMPLOYER_CONTRIBUTION_PERCENTAGE,
    t9.member_count_expiring as EXPIRING_MEMBER_COUNT,
    t2.risk_covered as FAMILY_DEFINITION_DESCRIPTION,
    t9.final_memb_count_atexpiry as FINAL_MEMBER_COUNT_AT_EXPIRY,
    t0.floater_or_not as FLOATER_INDICATOR,
    t9.member_emp_header as GROUP_SIZE,
    t9.empr_emp_relation as GROUP_TYPE,
    coalesce(t6.imd_code, t7.main_agent_code, t8.intermediary_code) as IMD_CODE,
    t3.intermediary as INTERMEDIARY_REFERENCE,
    t5.ctny_master_contract_id as MASTER_POLICY_NUMBER,
    t2.members_per_family as MAXIMUM_MEMBERS_PER_FAMILY,
    t9.age_bracket as MEMBER_AGE_BAND,
    coalesce(t2.total_member_count, t9.total_no_proposed) as MEMBER_COUNT,
    t9.addition_in_year as MEMBERS_ADDED_IN_YEAR,
    t9.deletion_inayear as MEMBERS_DELETED_IN_YEAR,
    t2.parental_si_restriction as PARENTAL_SUM_INSURED_RESTRICTION,
    t2.no_of_employees as PRIMARY_MEMBER_COUNT,
    t7.refer_date as REFERRAL_DATE,
    t7.refered_by_rule_engine as REFERRED_BY_RULE_ENGINE_INDICATOR,
    t7.refer_by as REFERRED_BY_USER_REFERENCE,
    coalesce(t7.main_agent_sc_amt, t8.main_agent_sc_amt) as SERVICE_CHARGE_AMOUNT,
    coalesce(t7.main_agent_sc_rate, t8.main_agent_sc_rate) as SERVICE_CHARGE_RATE,
    coalesce(t7.sub_agent_code, t8.sub_agent_code) as SUB_IMD_CODE,
    t1.deactive_pol_date as TERMINATION_DATE,
    t7.referral_reason as UNDERWRITER_REFERRAL_REASON
from t0
full outer join t1 on t1.HUB_POLICY_BK__POLICY_REF = t0.HUB_POLICY_BK__POLICY_REF
full outer join t2 on t2.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF)
full outer join t3 on t3.HUB_POLICY_BK__PMASTERPOLICYNUMBER = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF, t2.HUB_POLICY_BK__CONTRACT_ID)
full outer join t4 on t4.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF, t2.HUB_POLICY_BK__CONTRACT_ID, t3.HUB_POLICY_BK__PMASTERPOLICYNUMBER)
full outer join t5 on t5.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF, t2.HUB_POLICY_BK__CONTRACT_ID, t3.HUB_POLICY_BK__PMASTERPOLICYNUMBER, t4.HUB_POLICY_BK__CONTRACT_ID)
full outer join t6 on t6.HUB_POLICY_BK__POLICY_REF = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF, t2.HUB_POLICY_BK__CONTRACT_ID, t3.HUB_POLICY_BK__PMASTERPOLICYNUMBER, t4.HUB_POLICY_BK__CONTRACT_ID, t5.HUB_POLICY_BK__CONTRACT_ID)
full outer join t7 on t7.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF, t2.HUB_POLICY_BK__CONTRACT_ID, t3.HUB_POLICY_BK__PMASTERPOLICYNUMBER, t4.HUB_POLICY_BK__CONTRACT_ID, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__POLICY_REF)
full outer join t8 on t8.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__POLICY_REF, t1.HUB_POLICY_BK__POLICY_REF, t2.HUB_POLICY_BK__CONTRACT_ID, t3.HUB_POLICY_BK__PMASTERPOLICYNUMBER, t4.HUB_POLICY_BK__CONTRACT_ID, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__POLICY_REF, t7.HUB_POLICY_BK__CONTRACT_ID)
full outer join t9 on t9.HUB_ASSESSMENT_BK__SCRUTINY_NO = t2.HUB_ASSESSMENT_BK__SCRUTINY_NO
